const c4 = `@startuml
title <size:24>System Context View: Library</size>

set separator none
left to right direction

<style>
  root {
    BackgroundColor: #ffffff
    FontColor: #444444
  }
</style>

!include <C4/C4>
!include <C4/C4_Context>

Person(Patron, "Patron", $descr="Borrows books at the library.", $tags="", $link="")
System(Library, "Library", $descr="Manages books and loans.", $tags="", $link="")

Rel(Patron, Library, "Browses the catalogue through", $techn="HTTPS", $tags="", $link="")

SHOW_LEGEND(true)
hide stereotypes
@enduml`;

const res = await fetch("http://www.plantuml.com/plantuml/svg", {
  method: "POST",
  headers: { "Content-Type": "text/plain" },
  body: c4,
});
const text = await res.text();
return {
  status: res.status,
  contentType: res.headers.get("content-type"),
  length: text.length,
  head: text.slice(0, 400),
  hasError: /error|exception|!include/i.test(text.slice(0, 2000)),
};

